/* Shared native Unicode picker. Dataset and licence are bundled locally. */
(function(){'use strict';
const assetBase=new URL('.',document.currentScript.src);
const dialog=document.createElement('dialog');dialog.id='cage-emoji-dialog';dialog.className='app-dialog';dialog.setAttribute('aria-labelledby','cage-emoji-title');document.body.append(dialog);
let data=null,pending=null,selectEmoji=null,opener=null,limit=96,request=0;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function key(){return 'cage-emoji-recent:'+String(window.CAGE_BACKEND?.currentProfile?.()?.id||'anonymous');}
function recent(){try{return JSON.parse(localStorage.getItem(key())||'[]').filter(x=>typeof x==='string').slice(0,30);}catch{return [];}}
function remember(emoji){try{localStorage.setItem(key(),JSON.stringify([emoji,...recent().filter(x=>x!==emoji)].slice(0,30)));}catch{}}
async function load(){if(data)return data;if(!pending)pending=fetch(new URL('vendor/emoji-data.json?v=25.0.0',assetBase)).then(r=>{if(!r.ok)throw Error('Could not load emojis. Please try again.');return r.json();}).then(d=>{if(!Array.isArray(d.items)||!d.items.length)throw Error('Emoji catalogue is unavailable.');data=d.items;return data;}).finally(()=>{pending=null;});return pending;}
function render(){const query=dialog.querySelector('[data-emoji-search]').value.trim().toLowerCase();const category=dialog.querySelector('[data-emoji-category]').value;const tone=dialog.querySelector('[data-emoji-tone]').value;let source=category==='Recent'?recent().map(e=>data.find(x=>x.emoji===e)).filter(Boolean):data;const items=source.filter(x=>(category==='All'||category==='Recent'||x.category===category)&&(!query||query.split(/\s+/).every(word=>(x.name+' '+x.keywords+' '+x.emoji).toLowerCase().includes(word)))&&(!tone||x.emoji.includes(String.fromCodePoint(Number(tone)))));dialog.querySelector('[data-emoji-results]').innerHTML=items.slice(0,limit).map(x=>`<button type="button" data-pick-emoji="${esc(x.emoji)}" aria-label="${esc(x.name)}" title="${esc(x.name)}">${x.emoji}</button>`).join('');dialog.querySelector('[data-emoji-count]').textContent=items.length?`${Math.min(limit,items.length)} of ${items.length} emojis`:(category==='Recent'?'No recently used emojis yet.':'No emojis match. Try another word or category.');dialog.querySelector('[data-emoji-more]').hidden=limit>=items.length;}
async function open(trigger,onSelect){opener=trigger;selectEmoji=onSelect;const token=++request;dialog.innerHTML='<div class="dialog-heading"><h2 id="cage-emoji-title">Choose an emoji</h2><button type="button" class="secondary-button" data-emoji-close>Close</button></div><div data-emoji-body><p role="status">Loading emojis…</p></div>';if(!dialog.open)dialog.showModal();try{await load();if(token!==request||!dialog.open)return;dialog.querySelector('[data-emoji-body]').innerHTML=`<label class="field"><span>Search emojis</span><input type="search" data-emoji-search placeholder="Search smile, lunch, Malawi…" autocomplete="off"></label><div class="cage-emoji-filters"><label class="field"><span>Category</span><select data-emoji-category>${['All','Recent',...new Set(data.map(x=>x.category))].map(x=>`<option>${esc(x)}</option>`).join('')}</select></label><label class="field"><span>Skin tone</span><select data-emoji-tone><option value="">All tones</option>${['Light','Medium-light','Medium','Medium-dark','Dark'].map((x,i)=>`<option value="${127995+i}">${x}</option>`).join('')}</select></label></div><p data-emoji-count role="status"></p><div class="cage-full-emoji-grid" data-emoji-results></div><button type="button" class="secondary-button" data-emoji-more>Show more emojis</button><p class="cage-emoji-note">Standard Unicode emojis. Appearance may vary in other apps.</p>`;limit=96;render();dialog.querySelector('[data-emoji-search]').focus();}catch(e){if(token===request&&dialog.open)dialog.querySelector('[data-emoji-body]').innerHTML=`<p role="alert">${esc(e.message)}</p><button type="button" class="secondary-button" data-emoji-retry>Try again</button>`;}}
dialog.addEventListener('input',e=>{if(e.target.matches('[data-emoji-search]')){limit=96;render();}});dialog.addEventListener('change',e=>{if(e.target.matches('select')){limit=96;render();}});
dialog.addEventListener('click',e=>{if(e.target.closest('[data-emoji-close]'))dialog.close();if(e.target.closest('[data-emoji-retry]'))open(opener,selectEmoji);if(e.target.closest('[data-emoji-more]')){limit+=96;render();}const b=e.target.closest('[data-pick-emoji]');if(b){const emoji=b.dataset.pickEmoji;if(selectEmoji?.(emoji)===false)return;remember(emoji);dialog.close();}});
dialog.addEventListener('close',()=>{request++;if(opener?.isConnected)opener.focus();});
dialog.addEventListener('keydown',e=>{const b=e.target.closest('[data-pick-emoji]');if(!b||!['ArrowRight','ArrowLeft','ArrowDown','ArrowUp','Home','End'].includes(e.key))return;e.preventDefault();const list=[...dialog.querySelectorAll('[data-pick-emoji]')],i=list.indexOf(b),columns=getComputedStyle(b.parentElement).gridTemplateColumns.split(' ').length;const next=e.key==='Home'?0:e.key==='End'?list.length-1:i+({ArrowRight:1,ArrowLeft:-1,ArrowDown:columns,ArrowUp:-columns}[e.key]);list[Math.max(0,Math.min(list.length-1,next))]?.focus();});
window.CAGE_EMOJI={open};
const input=document.getElementById('chat-input'),tools=document.querySelector('.chat-compose-tools');if(input&&tools){const button=document.createElement('button');button.type='button';button.id='chat-emoji';button.textContent='☺ Emoji';button.setAttribute('aria-label','Add an emoji to your message');tools.append(button);button.addEventListener('click',()=>{const start=input.selectionStart,end=input.selectionEnd;open(button,emoji=>{if(input.disabled||input.readOnly)return false;if(input.maxLength>=0&&input.value.length-(end-start)+emoji.length>input.maxLength){dialog.querySelector('[data-emoji-count]').textContent='Your message is at its character limit. Shorten it before adding an emoji.';return false;}input.setRangeText(emoji,start,end,'end');input.dispatchEvent(new Event('input',{bubbles:true}));setTimeout(()=>input.focus(),0);return true;});});}
window.addEventListener('cage:session-ready',()=>{if(dialog.open)dialog.close();});
})();
